output_text:
[
  {
    "id": "no_cart_in_single_file_aisles",
    "text": "Shopping carts are forbidden in single-file shelf aisles.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileShelfAisle"
        ]
      }
    }
  },
  {
    "id": "enter_single_file_only_without_cart",
    "text": "A shopper must not enter a single-file shelf aisle while still holding a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {
        "enterSingleFileShelfAisle": {
          "pre": {
            "not": "singleFileShelfAisle"
          },
          "post": "singleFileShelfAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "enterSingleFileShelfAisle",
          "hasCart"
        ]
      }
    }
  },
  {
    "id": "retrieve_cart_after_parking",
    "text": "After parking or abandoning a cart, the shopper is obliged to retrieve a cart before finishing.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "cartDrop": {
          "pre": {
            "and": [
              "INTERACT",
              "hasCart"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cartDrop",
      "discharge": "hasCart"
    }
  },
  {
    "id": "cart_required_for_wide_shelf_service",
    "text": "Shelf interactions from wide or cart-accessible aisles require the shopper to have a cart, while narrow single-file shelf aisles are exempt.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "wideShelfServicePoint": {
          "and": [
            "adjShelf",
            {
              "not": "singleFileShelfAisle"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          "wideShelfServicePoint",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "cart_transfers_only_at_bays_or_aisle_mouths",
    "text": "Cart pickup and cart drop-off are allowed only at the cart bay or at designated mouths of narrow shelf aisles.",
    "abstraction": {
      "state_properties": {
        "cartBay": "at(1,7)",
        "narrowAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "cartTransferPoint": {
          "or": [
            "cartBay",
            "narrowAisleMouth"
          ]
        }
      },
      "events": {
        "cartPickup": {
          "pre": {
            "and": [
              "INTERACT",
              {
                "not": "hasCart"
              }
            ]
          },
          "post": "hasCart"
        },
        "cartDrop": {
          "pre": {
            "and": [
              "INTERACT",
              "hasCart"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          {
            "or": [
              "cartPickup",
              "cartDrop"
            ]
          },
          {
            "not": "cartTransferPoint"
          }
        ]
      }
    }
  },
  {
    "id": "pickup_cart_after_leaving_single_file",
    "text": "On returning from a single-file shelf aisle to a wide aisle, the shopper is obliged to pick up the cart again.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "wideAisle": {
          "ge": [
            "freeWidthH",
            6
          ]
        }
      },
      "events": {
        "leaveSingleFileForWideAisle": {
          "pre": "singleFileShelfAisle",
          "post": "wideAisle"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "leaveSingleFileForWideAisle",
      "discharge": "hasCart"
    }
  },
  {
    "id": "one_way_no_west_with_cart",
    "text": "Cart traffic in the store follows a one-way circulation rule that forbids moving west while pushing a cart.",
    "abstraction": {
      "state_properties": {
        "publicShoppingAisle": {
          "or": [
            {
              "ge": [
                "freeWidthH",
                2
              ]
            },
            {
              "ge": [
                "freeWidthV",
                5
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "W",
          "hasCart",
          "publicShoppingAisle"
        ]
      }
    }
  },
  {
    "id": "exit_only_from_checkout_with_cart",
    "text": "The shopper may exit only from the checkout exit cell and only while still having the cart.",
    "abstraction": {
      "state_properties": {
        "checkoutExit": "at(11,7)"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          {
            "or": [
              {
                "not": "checkoutExit"
              },
              {
                "not": "hasCart"
              }
            ]
          }
        ]
      }
    }
  }
]
